# Simulating what _schedule_next_run does:
period = datetime.timedelta(hours=1)
next_run = datetime.datetime.now() + period
print(f'After +period: {next_run}')

kwargs = {'second': 0, 'microsecond': 0, 'hour': 0, 'minute': 10}
next_run = next_run.replace(**kwargs)
print(f'After replace: {next_run}')

tz = pytz.timezone('Asia/Kathmandu')
converted = tz.localize(next_run).astimezone().replace(tzinfo=None)
print(f'After localize+astimezone: {converted}')

